#pragma once

// Layout of the shader table generated by cmake/EmbedShaders.cmake. Internal to the renderer.

#include <cstddef>
#include <cstdint>

namespace Paralax::EmbeddedShaders {

	struct Entry
	{
		const char* Name;
		const uint8_t* Data;
		size_t Size;
	};

	extern const Entry* const g_Entries;
	extern const size_t g_EntryCount;

}
